def fit(c3,w,extra):
    cols=[x**1.5,(x/(1+c3*x))*v]
    for e in extra:
        if e=='sin': cols.append(np.sin(w*t))
        if e=='cos': cols.append(np.cos(w*t))
        if e=='xsin': cols.append(x*np.sin(w*t))
        if e=='xcos': cols.append(x*np.cos(w*t))
        if e=='vsin': cols.append(v*np.sin(w*t))
        if e=='vcos': cols.append(v*np.cos(w*t))
    A=np.column_stack(cols)
    coef,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.sum((dv_dt-A@coef)**2)/np.sum((dv_dt-dv_dt.mean())**2),coef
